INSERT INTO organization.event VALUES ('a8f2b29f-634e-4e56-a2f7-d3a3e7e1f8e0', 'Augustiner-Keller', 'Relaxed year-end dinner with the whole team. Great food, cold beer, and a look back at the highlights of the year.', NULL , '2025-12-20 19:00:00', 150, 'YEAR_END_PARTY', 'Arnulfstraße 52, 80335 München');
INSERT INTO organization.event VALUES ('c0b7a9de-42c0-4e1c-8358-d8f6f7d8f7c1', 'Lost Weekend', 'Casual after-work meetup with coffee, snacks, and short lightning talks. Great chance to connect across teams.', NULL , '2024-11-06 17:00:00', 50, 'WINTER_EVENT', 'Schellingstraße 3, 80779 München');
INSERT INTO organization.event VALUES ('9f5a4dbf-e15d-4c8b-8d51-fb9a3e07f289', 'Alte Utting', 'Laid-back summer hangout on the ship with drinks, music, and rooftop views. Just time to catch up and enjoy the sun.', NULL , '2024-06-25 15:00:00', 75, 'SUMMER_EVENT', 'Lagerhausstraße 15, 81371 München');
INSERT INTO organization.event VALUES ('d624cc6d-98ea-4d27-9f04-14d47ef55856', 'Café Münchner Freiheit', 'Small informal meetup to welcome new colleagues and casually chat about project ideas and team topics.', NULL , '2023-12-05 17:00:00', 50, 'WINTER_EVENT', 'Leopoldstraße 82, 80802 München');
INSERT INTO organization.event VALUES ('f1c9d9f4-7a5e-4d91-9fcb-2c9d1c3b7bfa', 'Käfer-Schänke', 'Dinner in a small group focused on sharing ideas between project leads and management. Great food, relaxed setting.', NULL , '2023-06-23 18:30:00', 40, 'SUMMER_EVENT', 'Prinzregentenstraße 73, 81675 München');
